package com.lingualearn.app.data.content

/**
 * Arabic (ar) and Turkish (tr) comprehensive curriculum content.
 * 10 levels × 6 topics = 60 distinct lessons per language.
 */
object ArabicCurriculum {
    fun getContent(level: Int, topic: String): CurriculumLessonContent {
        return when (level) {
            1 -> when (topic) {
                "Greetings" -> CurriculumLessonContent("السلام عليكم / مرحباً", "Peace be upon you / Hello", "as-sah-LAH-moo ah-LAY-koom / MAHR-hah-bahn", "السلام عليكم! كيف حالك اليوم؟", "Peace be upon you! How are you today?", "Reply to 'As-salamu alaykum' with 'Wa alaykumu s-salam'.")
                "Introducing Yourself" -> CurriculumLessonContent("اسمي عمر، تشرفت بمعرفتك", "My name is Omar, honored to meet you", "ees-MEE OH-mahr, tuh-SHAR-ruhf-too", "اسمي عمر وأنا من القاهرة.", "My name is Omar and I am from Cairo.", "'Ismi' (my name) followed by 'tasharraftu' (honored to meet you).")
                "Yes / No / Basic Responses" -> CurriculumLessonContent("نعم / لا / من فضلك / شكراً", "Yes / No / Please / Thank you", "NAH-ahm / laa / min FUD-lik / SHOOK-rahn", "نعم، من فضلك، شكراً جزيلاً.", "Yes, please, thank you very much.", "'Afwan' is the polite response to 'Shukran' (you're welcome).")
                "Numbers 1–10" -> CurriculumLessonContent("واحد، اثنان، ثلاثة، أربعة، خمسة...", "1 to 10 numerals", "WAA-hid, eeth-NAAN, thah-LAA-thah", "أريد فنجانين من الشاي، من فضلك.", "I would like two cups of tea, please.", "Arabic has a specific dual form for counting two items.")
                "Basic Pronouns" -> CurriculumLessonContent("أنا، أنتَ، أنتِ، هو، هي، نحن", "I, you (m), you (f), he, she, we", "AH-nah, AN-tah, AN-tee, HOO-wah, HEE-yah, NAH-noo", "نحن نتعلم اللغة العربية الفصحى معاً.", "We are learning Modern Standard Arabic together.", "Arabic distinguishes masculine and feminine 'you' (anta / anti).")
                else -> CurriculumLessonContent("عفواً و مع السلامة", "Excuse me and Goodbye", "AHF-wahn / mah-ah sah-LAA-mah", "عفواً، أين المحطة المركزية؟", "Excuse me, where is the central station?", "'Ma'a as-salama' literally means 'with peace'.")
            }
            2 -> when (topic) {
                "Family" -> CurriculumLessonContent("العائلة (الأب، الأم، الأخ، الأخت)", "Family (father, mother, brother, sister)", "al-AH-ee-lah", "أخي يدرس في جامعة دمشق وأختي مهندسة.", "My brother studies at Damascus University and my sister is an engineer.", "Family ties are profoundly revered in Arab cultural values.")
                "Colors" -> CurriculumLessonContent("أحمر، أزرق، أصفر، أخضر، أبيض", "Red, Blue, Yellow, Green, White", "AHH-mahr, AHZ-rahk, AHS-fahr, AKH-dahr", "السماء زرقاء والحديقة خضراء جميلة.", "The sky is blue and the garden is beautifully green.", "Color adjectives have masculine and feminine patterns (ahmar / hamra).")
                "Food" -> CurriculumLessonContent("الحمص، الفلافل، والقهوة العربية", "Hummus, falafel, and Arabic coffee", "al-HOOM-moos, al-fah-LAH-fil", "القهوة العربية مع التمر لذيذة جداً وتدل على الكرم.", "Arabic coffee with dates is delicious and signifies generosity.", "Poured traditionally from the decorative Dallah pot.")
                "Days & Months" -> CurriculumLessonContent("من الأحد إلى السبت", "From Sunday to Saturday", "min al-AH-hahd eelah as-SAHBT", "يوم الجمعة نجتمع لتناول طعام الغداء مع العائلة.", "On Friday we gather for lunch with the family.", "In Arabic, Sunday is 'Ahad' (the first day).")
                "Simple Questions" -> CurriculumLessonContent("من؟ ماذا؟ أين؟ متى؟ لماذا؟", "Who? What? Where? When? Why?", "mahn, MAA-dhaa, AY-nah, MAH-taa, lee-MAA-dhaa", "أين يقع الفندق الأقرب من هنا؟", "Where is the nearest hotel located from here?", "Questions are introduced clearly with interrogative particles.")
                else -> CurriculumLessonContent("أكل، شرب، ذهب، جاء", "Eat, drink, go, come", "AH-kah-lah, SHAH-ree-bah, DHAH-hah-bah", "ذهبت إلى المقهى وشربت الشاي بالنعناع.", "I went to the café and drank mint tea.", "Arabic verbs are based on three-letter triconsonantal roots.")
            }
            3 -> when (topic) {
                "Daily Routine" -> CurriculumLessonContent("الاستيقاظ مبكراً والرياضة", "Waking up early and exercising", "al-ees-tee-KAAZ moo-BAHK-kee-rahn", "أستيقظ في الساعة السادسة صباحاً كل يوم.", "I wake up at six in the morning every day.", "Daily schedules often revolve around sunrise and prayer times.")
                "Shopping" -> CurriculumLessonContent("كم سعر هذا؟", "How much is this?", "kahm SEH-eer HAA-dhaa", "كم ثمن هذه السجادة الحريرية الجميلة؟", "How much is this beautiful silk rug?", "Negotiating respectfully is an art form in traditional souqs.")
                "Time" -> CurriculumLessonContent("كم الساعة الآن؟", "What time is it right now?", "kahm as-SAAH-ah al-AAN", "الساعة الآن الثانية والنصف بعد الظهر.", "It is 2:30 in the afternoon right now.", "'Wa nisf' denotes half past the hour.")
                "Directions" -> CurriculumLessonContent("امشِ إلى الأمام وانعطف يميناً", "Walk straight ahead and turn right", "EEM-shee eelah al-ah-MAAM", "امشِ للأمام ثم انعطف يساراً عند المفترق.", "Walk ahead then turn left at the intersection.", "'Yameen' is right, 'yasaar' is left.")
                "Simple Sentences" -> CurriculumLessonContent("أريد زيارة المتحف القديم", "I want to visit the ancient museum", "oo-REE-doo zee-YAA-rah", "أريد أن أستمتع بجمال العمارة الإسلامية.", "I want to appreciate the beauty of Islamic architecture.", "Pair 'ureed an' directly with present verbs.")
                else -> CurriculumLessonContent("كيف تجري أمورك؟", "How are things going with you?", "KAY-fah TAJ-ree", "الحمد لله، كل شيء يسير على ما يرام.", "Praise be to God, everything is going well.", "'Alhamdulillah' is the natural, universal reply.")
            }
            4 -> when (topic) {
                "Past Events" -> CurriculumLessonContent("سافرتُ إلى الأردن أمس", "I traveled to Jordan yesterday", "SAH-fahr-too eelah al-OOR-doon", "زرنا البتراء الرائعة في يوم مشمس وممتع.", "We visited magnificent Petra on a sunny, pleasant day.", "Past tense conjugation adds suffixes: 'safartu' (I traveled).")
                "Future Plans" -> CurriculumLessonContent("سوف أسافر إلى دبي الشهر القادم", "I will travel to Dubai next month", "SOW-fah oo-SAA-feer", "سأتعلم الخط العربي في العطلة القادمة.", "I will learn Arabic calligraphy during the next vacation.", "Future is formed by prefixing 'sa-' or 'sawfa' before the verb.")
                "Travel" -> CurriculumLessonContent("تذكرة الطائرة ومطار دبي الدولي", "Flight ticket and Dubai Airport", "tudh-KEE-rah", "رحلتي الجوية متجهة إلى مطار القاهرة الدولي.", "My flight is bound for Cairo International Airport.", "Modern airports across the Gulf are global travel hubs.")
                "Restaurants" -> CurriculumLessonContent("الفاتورة، لو سمحت", "The bill, if you please", "al-fah-TOO-rah, low suh-MAHT", "كان الطعام لذيذاً جداً، الفاتورة لو سمحت.", "The food was very delicious, the bill please.", "'Law samaht' is a courteous way to ask servers.")
                "Describing People" -> CurriculumLessonContent("كريم، مضياف وشجاع", "Generous, hospitable, and brave", "kah-REEM, mood-YAAF", "صديقي شخص كريم جداً ومحب للجميع.", "My friend is a very generous person and loved by all.", "'Karam' (generosity) is among the highest virtues in Arab culture.")
                else -> CurriculumLessonContent("الطقس معتدل وجميل هذا المساء", "The weather is mild and pleasant tonight", "at-TUHKS moo-tah-DEEL", "نسيم الليل اللطيف يجعل السهر في الهواء الطلق ممتعاً.", "The gentle evening breeze makes sitting outdoors pleasant.", "Cool desert and coastal evenings invite conversation.")
            }
            5 -> when (topic) {
                "Longer Conversations" -> CurriculumLessonContent("هل لي بإبداء وجهة نظري؟", "May I express my viewpoint?", "hal lee bee-eeb-DAA", "أود أن أشارككم بعض الأفكار البناءة حول هذا الموضوع.", "I would like to share some constructive thoughts on this topic.", "Polite diplomatic phrasing in formal Arabic discourse.")
                "Opinions" -> CurriculumLessonContent("في رأيي المتواضع", "In my humble opinion", "fee RAH-yee al-moo-tah-WAA-dih", "في رأيي، الحفاظ على التراث يعزز الهوية الوطنية.", "In my opinion, preserving heritage strengthens national identity.", "'Fee ra'yee' introduces well-founded perspectives.")
                "Experiences" -> CurriculumLessonContent("تجربة ثقافية فريدة ومؤثرة", "A unique and moving cultural experience", "TAJ-ree-bah thah-KAA-fee-yah", "زيارة واحة سيوة كانت تجربة روحية لا تُنسى.", "Visiting Siwa Oasis was an unforgettable spiritual experience.", "Sharing profound reflections on cultural travel.")
                "Comparisons" -> CurriculumLessonContent("أفضل من / أكثر أهمية من", "Better than / More important than", "UHF-dahl min / AHK-thar uh-HEEM-mee-yah", "السفر بالقطار أريح بكثير من الحافلة.", "Traveling by train is much more comfortable than by bus.", "Comparative adjectives follow the 'af'al' pattern (ahsan, akbar).")
                "More Complex Grammar" -> CurriculumLessonContent("إذا... فإن (الجمل الشرطية)", "If... then (conditional sentences)", "EE-dhaa ... fuh-EHN", "إذا بذلتَ جهداً كافياً، فإنك ستحقق أهدافك بالتأكيد.", "If you exert sufficient effort, you will surely achieve your goals.", "Conditional particles link premises to outcomes with precision.")
                else -> CurriculumLessonContent("الاستماع إلى إذاعة بي بي سي العربية", "Listening to BBC Arabic radio broadcasts", "al-ees-tee-MAA", "أستمع للتقارير الإخبارية لصقل حاسة السمع اللغوي.", "I listen to news reports to sharpen linguistic auditory comprehension.", "Pay attention to emphatic consonants (Sad, Dad, Ta, Za).")
            }
            6 -> when (topic) {
                "Storytelling" -> CurriculumLessonContent("كان يا ما كان في قديم الزمان...", "Once upon a time in ancient days...", "KAAN yaa MAA KAAN", "حكايات ألف ليلة وليلة المليئة بالسحر والحكمة.", "Tales of the Arabian Nights filled with magic and wisdom.", "The timeless opening formula for Arabic storytelling.")
                "Workplace Conversations" -> CurriculumLessonContent("الاجتماع الدوري للمشاريع", "Periodic project review meeting", "al-eej-tee-MAA ad-DOW-ree", "سنناقش اليوم الخطة التنفيذية لتطوير أعمالنا.", "Today we will discuss the executive roadmap for business development.", "Executive Arabic balances classic formal registers with corporate terms.")
                "Social Situations" -> CurriculumLessonContent("أهلاً وسهلاً، شرفتم منزلنا", "Welcome, you have honored our home", "AH-lahn wa SAH-lahn", "حللتم أهلاً ووطئتم سهلاً، الدار داركم.", "You have arrived among family and stepped on gentle ground.", "Iconic poetic welcome rooted in Bedouin warmth.")
                "News & Media" -> CurriculumLessonContent("عناوين الصحف والتحليلات السياسية", "Newspaper headlines and political analyses", "ah-naa-WEEN as-SOO-hoof", "تسلط الافتتاحية الضوء على قمة التنمية الاقتصادية المستدامة.", "The editorial sheds light on the sustainable economic development summit.", "Journalistic Modern Standard Arabic.")
                "Idiomatic Expressions" -> CurriculumLessonContent("الوقت كالسيف إن لم تقطعه قطعك", "Time is like a sword: cut it or it cuts you", "al-WAHKT kas-SAYF", "استغل أوقاتك بما ينفع ولا تؤجل عمل اليوم إلى الغد.", "Utilize your time fruitfully and never postpone today's work.", "Famous Arabic proverb emphasizing urgency.")
                else -> CurriculumLessonContent("الممنوع من الصرف والإعراب", "Diptotes and case grammar endings", "al-muhm-NOO min as-SARF", "فهم علامات الرفع والنصب والجر بدقة بالغة.", "Understanding nominative, accusative, and genitive vowel markers.", "Vowel case endings (I'rab) form the bedrock of classical Arabic syntax.")
            }
            7 -> when (topic) {
                "Complex Conversations" -> CurriculumLessonContent("قضايا الاستدامة والتحول الرقمي", "Sustainability and digital transformation", "kah-DAA-yaa al-ees-teed-DAA-mah", "التوازن بين الأصالة المعاصرة والتحديث التقني السريع.", "The balance between contemporary authenticity and rapid tech modernization.", "Discuss high-register societal themes in eloquent MSA.")
                "Debate & Opinions" -> CurriculumLessonContent("المناظرة الفكرية والحوار الهادف", "Intellectual debate and purposeful dialogue", "al-moo-NAA-zah-rah", "أحترم رأيك الكريم، غير أنني أرى الأمر من زاوية أخرى.", "I respect your generous opinion, yet I view the matter from another angle.", "Diplomatic disagreement delivered with elegance.")
                "Abstract Topics" -> CurriculumLessonContent("فلسفة ابن رشد وابن خلدون", "Philosophy of Averroes and Ibn Khaldun", "EEBN ROOSHD wa EEBN khal-DOON", "مقدمة ابن خلدون أسست علم الاجتماع وفلسفة التاريخ.", "Ibn Khaldun's Muqaddimah founded sociology and historical philosophy.", "Arabic was the global language of scientific philosophy for centuries.")
                "Natural Expressions" -> CurriculumLessonContent("وضع النقاط على الحروف", "To dot the i's (clarify ambiguities completely)", "WAH-dah an-nee-KAAT", "تحدث بصراحة ووضع النقاط على الحروف دون مواربة.", "He spoke with complete clarity, laying everything out without ambiguity.", "Expressive Arabic idiom for resolving ambiguity.")
                "Listening Comprehension" -> CurriculumLessonContent("متابعة الخطابات الدبلوماسية الرسمية", "Following official diplomatic speeches", "khee-taa-BAAT", "استيعاب التراكيب البلاغية واللغة الرسمية الرفيعة بسهولة.", "Comprehending rhetorical structures and elevated formal language effortlessly.", "Auditory mastery of rapid diplomatic oratory.")
                else -> CurriculumLessonContent("المقالة التحليلية والبحث الأكاديمي", "Analytical essays and academic research", "al-mah-KAA-lah", "صياغة أطروحة علمية مبنية على الأدلة والتحليل المنطقي.", "Formulating a scholarly dissertation grounded in evidence and logic.", "Academic composition in classical prose.")
            }
            8 -> when (topic) {
                "Advanced Conversations" -> CurriculumLessonContent("التخطيط الاستراتيجي المستقبلي", "Futuristic strategic planning", "at-takh-TEET", "ينبغي اتخاذ قرارات استراتيجية مبنية على رؤية استشرافية.", "Strategic decisions must be formulated based on forward-looking vision.", "Executive leadership vocabulary.")
                "Cultural Context" -> CurriculumLessonContent("المعلقات الشعرية وعصر النهضة", "Pre-Islamic Mu'allaqat odes and Nahda", "al-moo-ahl-lah-KAAT", "المعلقات السبع تمثل قمة الفصاحة والبلاغة اللغوية في تاريخ العرب.", "The Seven Mu'allaqat represent the pinnacle of linguistic eloquence.", "Appreciating classic poetic meters.")
                "Nuanced Vocabulary" -> CurriculumLessonContent("السجايا، الفضائل والمآثر", "Noble innate traits and heroic virtues", "as-sah-JAA-yaa", "امتدح الشاعر مآثر أجداده وشجاعتهم في ساحات الشرف.", "The poet praised his ancestors' heroic deeds and honor.", "Elevated classical vocabulary.")
                "Advanced Listening" -> CurriculumLessonContent("فهم اللهجات العربية المتنوعة", "Understanding diverse Arabic dialects (Amiya)", "al-lah-jah-HAAT", "التمييز بين اللهجة الشامية، والمصرية، والخليجية، والمغاربية.", "Distinguishing Levantine, Egyptian, Gulf, and Maghrebi dialects.", "Arabic speakers navigate MSA and regional dialects fluidly.")
                "Formal vs Informal Speech" -> CurriculumLessonContent("الفصحى مقابل العاميات الدارجة", "Fusha versus everyday colloquial dialects", "al-FOOS-haa vs al-AHM-mee-yah", "استخدام الفصحى في الإعلام والمحافل الرسمية والعامية في الحياة اليومية.", "Using MSA in media and formal forums, and colloquial in daily life.", "Mastering diglossia with natural ease.")
                else -> CurriculumLessonContent("علم البلاغة: البيان والمعاني والبديع", "Science of Balagha: Rhetoric, meaning, and figures", "BAH-laa-ghah", "تذوق الاستعارات والجناس والطباق في النصوص الرفيعة.", "Savoring metaphors, alliteration, and antithesis in elevated texts.", "The three branches of classical Arabic rhetoric.")
            }
            9 -> when (topic) {
                "Professional Communication" -> CurriculumLessonContent("المعاهدات الدولية والاتفاقيات الثنائية", "International treaties and bilateral accords", "al-moo-ah-hah-DAAT", "وقّع الطرفان وثيقة تفاهم استراتيجي لتعزيز التعاون الاقتصادي.", "Both parties signed a strategic MoU to bolster economic cooperation.", "High diplomatic and ministerial Arabic.")
                "Advanced Reading" -> CurriculumLessonContent("روائع الأدب: نجيب محفوظ وجبران", "Literary masterpieces: Naguib Mahfouz and Gibran", "nah-GEEB mah-FOOZ", "قراءة ثلاثية القاهرة واستيعاب العمق النفسي والاجتماعي للشخصيات.", "Reading the Cairo Trilogy and absorbing the characters' psychological depth.", "Nobel laureate literature in the original Arabic.")
                "Idioms & Expressions" -> CurriculumLessonContent("قطعت جهيزة قول كل خطيب", "The definitive word has ended all debate", "kah-tah-aht jah-HEE-zah", "صدر الحكم القضائي النهائي فقطعت جهيزة قول كل خطيب.", "The final verdict was delivered, putting an absolute end to all debate.", "Famous classical idiom used when a decisive matter is settled.")
                "Advanced Writing" -> CurriculumLessonContent("الأطروحات الفكرية والدراسات النقدية", "Intellectual treatises and critical studies", "al-oht-ROO-haat", "تقديم رؤية نقدية معمقة تستند إلى مراجع تاريخية موثوقة.", "Offering an in-depth critique grounded in verified historical sources.", "Publishable scholarly prose.")
                "Difficult Listening" -> CurriculumLessonContent("الخطب البرلمانية والنقاشات الدبلوماسية الحية", "Parliamentary speeches and live diplomatic debates", "an-nee-KAA-shaat", "التقاط الدلالات الرمزية والتلميحات الذكية دون أدنى عناء.", "Capturing symbolic allusions and sharp wit without the slightest effort.", "Auditory comprehension of fast-paced rhetoric.")
                else -> CurriculumLessonContent("الفصاحة المطلقة والبيان الساحر", "Absolute eloquence and captivating clarity", "al-fah-SAAH-hah", "الحديث بلغة عربية فصحى ساحرة تأسر عقول المستمعين.", "Speaking in captivating Arabic prose that enchants the minds of listeners.", "Bilingual near-native eloquence.")
            }
            else -> when (topic) {
                "Natural Conversation" -> CurriculumLessonContent("طلاقة لسان وانسيابية تامة", "Flawless fluency and natural verbal flow", "tuh-LAA-kah", "الحديث بارتياح وثقة مطلقة مستخدماً كل مفردات الفصاحة.", "Speaking with ease and absolute confidence, utilizing full vocabulary.", "Effortless native cadence.")
                "Humor & Cultural References" -> CurriculumLessonContent("طرائف جحا والنكتة البلاغية الراقية", "Tales of Juha and refined satirical wit", "tuh-RAA-eef JOO-hah", "فهم النكتة الذكية والتورية اللفظية التي تعكس عمق الثقافة.", "Understanding witty puns and cultural double entendres.", "Culturally grounded humor.")
                "Advanced Debates" -> CurriculumLessonContent("الخطابة المفوهة وقوة الحجة", "Commanding oratory and irresistible argument", "al-khee-TAA-bah", "إقناع الجماهير بحجج دامغة وبلاغة لفظية لا تُضاهى.", "Persuading audiences with decisive arguments and unmatched eloquence.", "Mastery over public oration.")
                "Professional Fluency" -> CurriculumLessonContent("القيادة في المحافل الإقليمية والدولية", "Leadership in regional and international forums", "al-kee-YAA-dah", "إدارة المؤتمرات والقمم الاقتصادية الدولية باللغة العربية باقتدار.", "Managing international summits and leadership forums in Arabic with distinction.", "Executive diplomatic leadership.")
                "Native-Speed Listening" -> CurriculumLessonContent("الإدراك السمعي الفوري والتلقائي", "Instant, instinctive auditory perception", "al-eed-RAAK as-SAHM-ee", "استيعاب أدق الكلمات في أصعب المواقف الحوارية السريعة.", "Absorbing the most subtle words even in rapid-fire dialogue.", "Flawless acoustic mastery.")
                else -> CurriculumLessonContent("الاندماج التام في الوجدان العربي", "Complete immersion in the Arab cultural ethos", "al-een-dee-MAAJ", "العيش والتفكير بعمق وجمال اللغة العربية الفصحى الأصيلة.", "Living and thinking within the profound beauty of authentic Arabic.", "Ultimate linguistic and cultural mastery.")
            }
        }
    }
}

object TurkishCurriculum {
    fun getContent(level: Int, topic: String): CurriculumLessonContent {
        return when (level) {
            1 -> when (topic) {
                "Greetings" -> CurriculumLessonContent("Merhaba! / Günaydın", "Hello! / Good morning", "MEHR-hah-bah / goon-eye-DUHN", "Merhaba! Bugün nasılsınız?", "Hello! How are you today? (polite)", "'Kolay gelsin' is an iconic Turkish greeting wishing ease at work.")
                "Introducing Yourself" -> CurriculumLessonContent("Benim adım Mehmet", "My name is Mehmet", "beh-NEEM ah-DUHM meh-MET", "Benim adım Mehmet, İstanbul'da yaşıyorum.", "My name is Mehmet, I live in Istanbul.", "'Benim adım' (my name) is the standard polite self-introduction.")
                "Yes / No / Basic Responses" -> CurriculumLessonContent("Evet / Hayır / Lütfen / Teşekkürler", "Yes / No / Please / Thank you", "eh-VET / hah-YUHR / LOOT-fen / teh-shek-koor-LEHR", "Evet, lütfen! Yardımlarınız için çok teşekkür ederim.", "Yes, please! Thank you very much for your help.", "'Rica ederim' is the polite response to thank you (you're welcome).")
                "Numbers 1–10" -> CurriculumLessonContent("Bir, iki, üç, dört, beş...", "1 to 10 numerals", "beer, ee-kee, ooch, doert, besh", "İki çay ve bir simit alabilir miyim, lütfen?", "May I have two teas and a simit, please?", "Simit and Turkish tea are Istanbul's iconic street pair.")
                "Basic Pronouns" -> CurriculumLessonContent("Ben, sen, o, biz, siz, onlar", "I, you, he/she/it, we, you all, they", "ben, sen, oh, beez, seez, ohn-LAHR", "Biz hep birlikte Türkçe öğreniyoruz.", "We are all learning Turkish together.", "Turkish has no grammatical gender: 'o' means he, she, and it.")
                else -> CurriculumLessonContent("Affedersiniz ve Hoşça kalın", "Excuse me / Pardon and Goodbye", "ahf-feh-dehr-SEE-neez / hohsh-CHAH kah-LUHN", "Affedersiniz, metro istasyonu nerede?", "Excuse me, where is the subway station?", "The person staying says 'Güle güle', the one leaving says 'Hoşça kalın'.")
            }
            2 -> when (topic) {
                "Family" -> CurriculumLessonContent("Aile (Anne, baba, ağabey, abla)", "Family (mother, father, elder brother, elder sister)", "ah-ee-LEH", "Ablam Ankara'da avukatlık yapıyor.", "My elder sister works as a lawyer in Ankara.", "Turkish has specific terms for elder siblings: 'ağabey' and 'abla'.")
                "Colors" -> CurriculumLessonContent("Kırmızı, mavi, sarı, yeşil, beyaz", "Red, Blue, Yellow, Green, White", "kuhr-muh-ZUH, mah-VEE, sah-RUH", "Mavi gözlü kedi pencerenin önünde uyuyor.", "The blue-eyed cat is sleeping in front of the window.", "Colors precede nouns without changing form.")
                "Food" -> CurriculumLessonContent("Kebap, baklava ve Türk kahvesi", "Kebab, baklava, and Turkish coffee", "keh-BAHP, bahk-lah-VAH", "Yemekten sonra orta şekerli bir Türk kahvesi içeriz.", "After the meal we drink a medium-sweet Turkish coffee.", "'Afiyet olsun' (bon appétit) is said warmly before and after meals.")
                "Days & Months" -> CurriculumLessonContent("Pazartesi'den Pazar'a", "Monday to Sunday", "pah-zahr-TEH-see-den PAH-zahr-ah", "Cumartesi akşamı Boğaz kenarında buluşacağız.", "Saturday evening we will meet by the Bosphorus.", "Turkish day names relate to market days (Pazar, Pazar-ertesi).")
                "Simple Questions" -> CurriculumLessonContent("Kim? Ne? Nerede? Ne zaman? Neden?", "Who? What? Where? When? Why?", "keem, neh, NEH-reh-deh, neh zah-MAHN, neh-DEN", "En yakın vapur iskelesi nerede?", "Where is the nearest ferry dock located?", "Questions form using harmonic question particles: 'mı / mi / mu / mü'.")
                else -> CurriculumLessonContent("Yemek, içmek, gitmek, gelmek", "Eat, drink, go, come", "yeh-MEK, eech-MEK, geet-MEK, gel-MEK", "Akşamları arkadaşlarımla çay bahçesine gidiyorum.", "In the evenings I go to the tea garden with my friends.", "Verb infinitives end in '-mek' or '-mak' following vowel harmony.")
            }
            3 -> when (topic) {
                "Daily Routine" -> CurriculumLessonContent("Erken kalkmak ve kahvaltı yapmak", "Waking up early and having breakfast", "ehr-KEN kahlk-MAHK", "Her sabah saat yedide uyanıp kahvaltı yaparım.", "Every morning I wake up at seven and have breakfast.", "The Turkish breakfast ('kahvaltı') is a lavish feast of olives, cheese, and tea.")
                "Shopping" -> CurriculumLessonContent("Bunun fiyatı ne kadar?", "How much is the price of this?", "boo-NOON fee-yah-TUH", "Bu el dokuması kilim ne kadar? Biraz indirim yapar mısınız?", "How much is this hand-woven kilim? Could you give a small discount?", "Bargaining with tea in hand is customary in the Grand Bazaar.")
                "Time" -> CurriculumLessonContent("Saat kaç?", "What time is it?", "sah-AHT kahch", "Saat şu anda öğleden sonra iki buçuk.", "It is 2:30 in the afternoon right now.", "'Buçuk' denotes half past with numerals; 'yarım' means half a piece.")
                "Directions" -> CurriculumLessonContent("Düz gidin ve sağa dönün", "Go straight and turn right", "dooz GEE-deen, sah-AH doe-NOON", "Trafiğe dikkat ederek ışıklardan sola dönün.", "Paying attention to traffic, turn left at the lights.", "'Sağ' is right, 'sol' is left.")
                "Simple Sentences" -> CurriculumLessonContent("Türkçe kitap okumak istiyorum", "I want to read a Turkish book", "ees-tee-YOH-room", "Hafta sonu Boğaz kıyısında yürüyüş yapmak istiyorum.", "On the weekend I want to take a walk along the Bosphorus shoreline.", "Pattern: Infinitive + 'istiyorum' (I want).")
                else -> CurriculumLessonContent("Nasıl gidiyor? Ne var ne yok?", "How's it going? What's new?", "nah-SUHL gee-dee-YOR", "İyilik sağlık, her şey yolunda.", "Wellness and health, everything is on track.", "Classic warm Turkish colloquial check-in.")
            }
            4 -> when (topic) {
                "Past Events" -> CurriculumLessonContent("Dün Ayasofya'yı ziyaret ettim", "Yesterday I visited Hagia Sophia", "doon ah-yah-SOHF-yah-yuh", "Dün tarihi yarımadayı hayranlıkla gezdik.", "Yesterday we toured the historical peninsula with admiration.", "Past tense suffix '-di / -ti' indicates direct witnessed past.")
                "Future Plans" -> CurriculumLessonContent("Gelecek ay Kapadokya'ya gideceğim", "I will go to Cappadocia next month", "geh-leh-JEK eye", "Yaz tatilinde Ege sahillerini gezeceğiz.", "During summer vacation we will tour the Aegean coasts.", "Future tense marker '-ecek / -acak' undergoes consonant softening (k -> ğ).")
                "Travel" -> CurriculumLessonContent("İstanbul Şehir Hatları Vapuru", "Istanbul City Lines Ferry", "sheh-HEER haht-lah-RUH vah-poo-ROO", "Kadıköy'den Eminönü'ne geçen vapura bindik.", "We boarded the ferry crossing from Kadıköy to Eminönü.", "Ferry travel is the poetic highlight of commuting in Istanbul.")
                "Restaurants" -> CurriculumLessonContent("Hesabı alabilir miyiz, lütfen?", "May we have the bill, please?", "heh-sah-BUH ah-lah-bee-leer", "Yemekler harikaydı, elinize sağlık! Hesabı alabilir miyiz?", "The food was wonderful, health to your hands! May we have the bill?", "'Elinize sağlık' (health to your hands) graciously compliments the cook.")
                "Describing People" -> CurriculumLessonContent("Misafirperver, samimi ve çalışkan", "Hospitable, sincere, and hardworking", "mee-sah-feer-pehr-VEHR", "Türk insanı son derece misafirperver ve candandır.", "Turkish people are exceptionally hospitable and sincere.", "Turkish culture places supreme value on welcoming guests warmly.")
                else -> CurriculumLessonContent("Bugün hava pırıl pırıl ve güneşli", "Today the weather is sparkling and sunny", "puh-RUHL puh-ruhl", "Güneş açtı, deniz kenarında çay içmek için harika bir gün.", "The sun came out; a fantastic day to drink tea by the sea.", "Vivid reduplicated adverbs like 'pırıl pırıl' enliven Turkish speech.")
            }
            5 -> when (topic) {
                "Longer Conversations" -> CurriculumLessonContent("Ben de bir fikir belirtebilir miyim?", "May I express an idea as well?", "bee-LEER-teh-bee-leer", "Bu projenin gidişatı hakkında görüşlerimi paylaşmak isterim.", "I'd like to share my opinions regarding this project's progress.", "Polite participative conversational formulas.")
                "Opinions" -> CurriculumLessonContent("Bana göre / Benim fikrime göre", "In my view / According to my opinion", "BAH-nah goe-reh", "Bana göre sanat ve edebiyat toplumun ruhunu besler.", "In my view, art and literature nourish the soul of society.", "'Bana göre' introduces personal reflections gracefully.")
                "Experiences" -> CurriculumLessonContent("Unutulmaz bir seyahat tecrübesi", "An unforgettable travel experience", "oo-noo-tool-MAHZ", "Kapadokya'da sıcak hava balonuna binmek muhteşemdi.", "Riding a hot air balloon in Cappadocia was magnificent.", "Recounting milestone travel memories.")
                "Comparisons" -> CurriculumLessonContent("İstanbul Ankara'dan daha kalabalıktır", "Istanbul is more crowded than Ankara", "DAH-hah kah-lah-bah-LUHK", "Hızlı tren otobüsten çok daha konforludur.", "The high-speed train is much more comfortable than the bus.", "Pattern: A, B'den 'daha' [adjective].")
                "More Complex Grammar" -> CurriculumLessonContent("Eğer... ise (Şart kipi)", "If... condition (-se / -sa)", "eh-EHR ... ee-seh", "Zamanın olursa müzeleri beraber gezelim.", "If you have time, let's explore the museums together.", "Conditional suffixes attach harmonically to verb stems.")
                else -> CurriculumLessonContent("Türkçe podcast ve radyo dinleme", "Listening to Turkish podcasts and radio", "deen-LEH-meh", "TRT Radyo dinleyerek telaffuzumu geliştiriyorum.", "I improve my pronunciation by listening to TRT Radio.", "Focus on pure front and back vowel harmony.")
            }
            6 -> when (topic) {
                "Storytelling" -> CurriculumLessonContent("Bir varmış, bir yokmuş...", "Once upon a time (there was and wasn't)...", "beer VAHR-muhsh, beer YOHK-moosh", "Evvel zaman içinde, kalbur saman içinde...", "In ancient times, in days of sieve and hay...", "The enchanting traditional opening of Turkish fairy tales.")
                "Workplace Conversations" -> CurriculumLessonContent("İş toplantısı ve proje değerlendirmesi", "Business meeting and project evaluation", "TOHP-lahn-tuh-suh", "Üçüncü çeyrek hedeflerimizi masaya yatırıp analiz ettik.", "We laid our third-quarter milestones on the table and analyzed them.", "Corporate Turkish is vibrant, collaborative, and results-oriented.")
                "Social Situations" -> CurriculumLessonContent("Tanrı misafiri ve ev sahipliği", "God's guest and gracious hosting", "tahn-RUH mee-sah-fee-REE", "Evimize şeref verdiniz, başımızın üstünde yeriniz var.", "You brought honor to our home; you have a place above our heads.", "Expresses boundless reverence for visiting guests.")
                "News & Media" -> CurriculumLessonContent("Günlük basın ve köşe yazıları", "Daily press and newspaper columns", "kœ-SHEH yah-zuh-lah-ruh", "Gazeteler ekonomik reformları ve teknolojik atılımları tartışıyor.", "Newspapers discuss economic reforms and technological breakthroughs.", "Journalistic Turkish is incisive and rich.")
                "Idiomatic Expressions" -> CurriculumLessonContent("Damlaya damlaya göl olur", "Drop by drop becomes a lake", "dahm-lah-YAH gœl oh-LOOR", "Küçük birikimler zamanla büyük zenginliklere dönüşür.", "Small savings transform into great wealth over time.", "Timeless proverb celebrating patience and steady thrift.")
                else -> CurriculumLessonContent("Geniş zaman ve dolaylı anlatım (-miş)", "Aorist tense and hearsay -miş suffix", "geh-NEESH zah-mahn", "Dün gece şiddetli bir fırtına çıkmış.", "Apparently a fierce storm broke out last night.", "The '-miş' suffix expresses reported, hearsay, or unobserved past.")
            }
            7 -> when (topic) {
                "Complex Conversations" -> CurriculumLessonContent("Toplumsal dönüşüm ve kentleşme", "Societal transformation and urbanization", "tohp-loom-SAHL doe-noo-SHOOM", "Geleneksel mahalle kültürü ile modern yaşamın sentezi.", "The synthesis of traditional neighborhood culture and modern living.", "Debating complex cultural sociological themes in refined Turkish.")
                "Debate & Opinions" -> CurriculumLessonContent("Karşıt argümanları nezaketle sunmak", "Presenting counter-arguments with courtesy", "kahr-SHUHT ahr-goo-MAHN", "Görüşlerinize saygı duymakla birlikte, farklı verilere dayanıyorum.", "While respecting your opinions, I rely on different data.", "Diplomatic dissent conducted with intellectual poise.")
                "Abstract Topics" -> CurriculumLessonContent("Mevlana Celaleddin Rumi ve tasavvuf", "Mevlana Rumi and Sufi philosophy", "mehv-LAH-nah roo-MEE", "Gel, ne olursan ol, yine gel — sevgi ve hoşgörü felsefesi.", "'Come, whoever you are, come again' — the philosophy of universal love.", "Rumi's humanistic mysticism has shaped Turkish spirituality.")
                "Natural Expressions" -> CurriculumLessonContent("Gözden geçirmek / İğne atsan yere düşmez", "To review / Packed so tight a needle wouldn't hit the ground", "gœz-DEN geh-cheer-MEK", "Kapalıçarşı o kadar kalabalıktı ki iğne atsan yere düşmezdi.", "The Grand Bazaar was so crowded that a needle wouldn't hit the floor.", "Colorful idioms describing vivid real-world scenes.")
                "Listening Comprehension" -> CurriculumLessonContent("Akademik konferans ve açık oturum", "Academic conferences and public panel debates", "ah-chuhk oh-too-ROOM", "Konuşmacıların hızlı tartışmalarını ve tezlerini eksiksiz kavramak.", "Completely grasping speakers' rapid arguments and theses without gap.", "Comprehending rapid spoken Turkish rhetoric.")
                else -> CurriculumLessonContent("Fikir yazısı ve deneme kaleme almak", "Drafting opinion essays and critiques", "DEH-neh-meh", "Giriş, gelişme ve sonuç bölümleriyle tutarlı bir makale.", "A coherent essay with introduction, development, and conclusion.", "High academic Turkish writing standards.")
            }
            8 -> when (topic) {
                "Advanced Conversations" -> CurriculumLessonContent("Stratejik vizyon ve kriz yönetimi", "Strategic vision and crisis management", "strah-teh-ZHEEK veez-YOHN", "Riskleri asgariye indirmek için çok yönlü bir eylem planı şarttır.", "A multifaceted action plan is essential to minimize risks.", "Executive management and policy vocabulary.")
                "Cultural Context" -> CurriculumLessonContent("Divan edebiyatı ve halk ozanları", "Divan court literature and folk bards", "dee-VAHN eh-deh-bee-yah-TUH", "Yunus Emre'nin duru Türkçesi ve Aşık Veysel'in ezgileri.", "Yunus Emre's lucid Turkish and Aşık Veysel's soulful folk songs.", "Centuries of folk and court poetry enrich linguistic expression.")
                "Nuanced Vocabulary" -> CurriculumLessonContent("Müstesna, vefakâr ve samimi", "Exceptional, loyal, and heartfelt", "moos-tes-NAH / veh-fah-KAAR", "Onun dostluğu gerçekten müstesna ve paha biçilmezdir.", "His friendship is truly exceptional and priceless.", "Rich Arabic and Persian loanwords integrated into literary Turkish.")
                "Advanced Listening" -> CurriculumLessonContent("Bölgesel ağızları ayırt etme", "Distinguishing regional Turkish dialects", "ah-UHZ-lah-ruh", "Karadeniz, Ege ve Doğu Anadolu ağızlarının melodik farkları.", "Melodic distinctions of Black Sea, Aegean, and Eastern Anatolian dialects.", "Understanding regional accents across Anatolia.")
                "Formal vs Informal Speech" -> CurriculumLessonContent("Resmi yazışma dili ve sokak Türkçesi", "Official administrative prose vs Colloquial slang", "res-MEE yah-zuhsh-MAH", "Devlet dairelerindeki bürokratik üslup ile günlük sokak dili.", "Bureaucratic style in public offices versus everyday street language.", "Effortless command across social registers.")
                else -> CurriculumLessonContent("Ettirgen ve edilgen fiil çatıları", "Causative and passive verb voices", "et-TEER-gen", "Raporu yöneticilere ayrıntılı bir şekilde onaylattık.", "We had the report comprehensively approved by the executives.", "Mastering causative chains (-dir, -t, -ir).")
            }
            9 -> when (topic) {
                "Professional Communication" -> CurriculumLessonContent("Uluslararası ticaret ve konsorsiyum", "International trade and consortium agreements", "kon-sor-see-YOOM", "Taraflar karşılıklı stratejik ortaklık anlaşmasını imzaladı.", "The parties signed the mutual strategic partnership agreement.", "Corporate negotiation and high commerce Turkish.")
                "Advanced Reading" -> CurriculumLessonContent("Orhan Pamuk ve Yaşar Kemal", "Orhan Pamuk and Yaşar Kemal masterworks", "ohr-HAHN pah-MOOK", "İnce Memed destanında Anadolu insanının hak arayışı.", "The quest for justice of Anatolian people in Memed, My Hawk.", "Appreciating Nobel-recognized literary masterworks.")
                "Idioms & Expressions" -> CurriculumLessonContent("Ağzıyla kuş tutsa nafile", "Even if he caught a bird in his mouth, it would be in vain", "ahg-ZUH-y-lah koosh toot-SAH", "Güveni bir kez kırıldı mı, ağzıyla kuş tutsa nafile.", "Once trust is broken, even catching a bird in one's mouth is in vain.", "Picturesque idiom describing irredeemable skepticism.")
                "Advanced Writing" -> CurriculumLessonContent("Akademik tez ve kuramsal tahlil", "Academic thesis and theoretical critique", "ah-kah-deh-MEEK tez", "Özgün veri analizi ile bilimsel literatüre katkıda bulunmak.", "Contributing to scientific literature through original data analysis.", "Standard publishable scholarly Turkish.")
                "Difficult Listening" -> CurriculumLessonContent("Meclis oturumları ve canlı münazaralar", "Parliamentary sessions and live debates", "mehj-LEES oh-too-room-lah-ruh", "Siyasi retorikteki kinaye ve imaları eksiksiz çözümlemek.", "Completely decoding irony and allusions in political rhetoric.", "Instant comprehension of high-speed debate.")
                else -> CurriculumLessonContent("Ana dil yetkinliğinde akıcı ifade", "Native-competence fluent expression", "yet-keen-LEEK", "Her türlü karmaşık konuyu zarafet ve ustalıkla açıklayabilmek.", "Ability to explain every complex topic with elegance and mastery.", "Effortless bilingual command.")
            }
            else -> when (topic) {
                "Natural Conversation" -> CurriculumLessonContent("Akıcı, tatlı ve pürüzsüz Türkçe", "Fluent, sweet, and seamless Turkish", "poo-rooz-SOOZ toork-CHEH", "Hiçbir tereddüt yaşamadan, su gibi berrak konuşabilmek.", "Speaking crystal clear like flowing water without hesitation.", "Effortless native cadence.")
                "Humor & Cultural References" -> CurriculumLessonContent("Nasreddin Hoca fıkraları ve nükte", "Nasreddin Hodja parables and sharp wit", "nahs-red-DEEN hoh-JAH", "Fıkralardaki derin hayat felsefesini ve hazırcevaplığı kavramak.", "Grasping the deep life philosophy and quick wit in folk parables.", "Culturally rooted humor.")
                "Advanced Debates" -> CurriculumLessonContent("Etkileyici hitabet sanatı", "Commanding and magnetic oratorical art", "hee-tah-BET sah-nah-TUH", "Coşkulu ve mantıklı bir hitabetle kitleleri peşinden sürüklemek.", "Captivating crowds with passionate and logical public speech.", "Mastery over public oration.")
                "Professional Fluency" -> CurriculumLessonContent("Küresel sahnede liderlik", "Leadership on the global stage", "koo-reh-SEL sah-neh", "Uluslararası zirvelerde Türk dünyasını yetkinlikle temsil etmek.", "Representing the Turkish world with competence at international summits.", "Supreme executive leadership.")
                "Native-Speed Listening" -> CurriculumLessonContent("Işık hızında dinleme ve algılama", "Light-speed listening and cognitive processing", "ahl-guh-lah-MAH", "En seri ve hararetli diyalogları bile anında özümsemek.", "Instantly absorbing even the most rapid and heated dialogues.", "Total auditory mastery.")
                else -> CurriculumLessonContent("Kültürel ve dilsel bütünleşme", "Complete cultural and linguistic synthesis", "boo-toon-lesh-MEH", "Türkçenin engin söz varlığını ve ruhunu bütünüyle yaşamak.", "Fully living the vast vocabulary and soulful spirit of Turkish.", "Total cultural and linguistic harmony.")
            }
        }
    }
}
